def evaluate(expr: str) -> int:
    def tokenize(expression):
        tokens = []
        num = ''
        for ch in expression:
            if ch.isdigit():
                num += ch
            else:
                if num:
                    tokens.append(num)
                    num = ''
                if ch in '+-*/()':
                    tokens.append(ch)
        if num:
            tokens.append(num)
        return tokens

    def precedence(op):
        if op in ('+', '-'):
            return 1
        if op in ('*', '/'):
            return 2
        return 0

    def apply_operator(operators, values):
        operator = operators.pop()
        right = values.pop()
        left = values.pop()
        if operator == '+':
            values.append(left + right)
        elif operator == '-':
            values.append(left - right)
        elif operator == '*':
            values.append(left * right)
        elif operator == '/':
            # Integer division truncating towards zero
            values.append(int(left / right))  # Python's int division rounds towards negative infinity

    def to_postfix(tokens):
        output = []
        operators = []
        for token in tokens:
            if token.isdigit():
                output.append(int(token))
            elif token in '+-*/':
                while (operators and
                       precedence(operators[-1]) >= precedence(token)):
                    output.append(operators.pop())
                operators.append(token)
            elif token == '(':
                operators.append(token)
            elif token == ')':
                while operators and operators[-1] != '(':
                    output.append(operators.pop())
                operators.pop()  # pop '('
        while operators:
            output.append(operators.pop())
        return output

    def evaluate_postfix(postfix_tokens):
        stack = []
        for token in postfix_tokens:
            if isinstance(token, int):
                stack.append(token)
            else:
                apply_operator([token], stack)
        return stack[0]

    tokens = tokenize(expr.replace(' ', ''))
    postfix_tokens = to_postfix(tokens)
    return evaluate_postfix(postfix_tokens)

